// Rule L3c at a pin: a node with several outputs passed straight to a pin is written with the output 1.x took.

/// @sort 32
uniform Texture2D Source;

/// @name DreamShaderTests/Migrate/M_MgNodeIntoPin
export void M_MgNodeIntoPin(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float2 uv = UE.TexCoord(Index = 0);
    float3 Faded = UE.Lerp(A = UE.TextureSample(TextureObject = Source, Coordinates = uv).RGB, B = 0.0, Alpha = 0.5);
    Color = Faded;
    Base.EmissiveColor = Color;
}
